package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("ಕೆಟ್ಟ ನೆರೆಹೊರೆಯವರಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಶಾಶ್ವತ ನಿವಾಸದ ಸ್ಥಳದಲ್ಲಿ ಕೆಟ್ಟ ನೆರೆಹೊರೆಯವನಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ, ಏಕೆಂದರೆ ಪ್ರಯಾಣದಲ್ಲಿರುವ ನೆರೆಹೊರೆಯವರು ಮುಂದುವರಿಯುತ್ತಾರೆ.", "ಕೆಟ್ಟ ನೆರೆಹೊರೆಯವರಿಂದ ರಕ್ಷಣೆಗಾಗಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರಿಂದ ಆಶ್ರಯ ಪಡೆಯಲು ಆದೇಶಿಸಿದರು."),
        "dua_ishfi_abdak" to DuaText("ಅನಾರೋಗ್ಯದಿಂದ ಚೇತರಿಸಿಕೊಳ್ಳಲು", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನ ಸೇವಕನು ನಿನಗಾಗಿ ಶತ್ರುವನ್ನು ಎದುರಿಸಲು ಅಥವಾ ನಿನಗಾಗಿ ಪ್ರಾರ್ಥನೆ ಮಾಡಲು ನಡೆಯಲು ಸಾಧ್ಯವಾಗುವಂತೆ ಅವನನ್ನು ಗುಣಪಡಿಸು.", "ಅನಾರೋಗ್ಯದಿಂದ ಬಳಲುತ್ತಿರುವ ವ್ಯಕ್ತಿಗೆ ಅವನನ್ನು ಭೇಟಿ ಮಾಡುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ರೋಗಿಗಳಿಗಾಗಿ ಇದನ್ನು ಹೇಳುವುದನ್ನು ಕಲಿಸಿದರು."),
        "dua_la_mania" to DuaText("ನೀವು ಏನು ನೀಡುತ್ತೀರೋ ಅದನ್ನು ಯಾರೂ ತಡೆಹಿಡಿಯಲು ಸಾಧ್ಯವಿಲ್ಲ.", "ಅಲ್ಲಾಹನೇ ಹೊರತು, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದ, ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಸೇರಿದ್ದು, ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಸೇರಿದ್ದು, ಅವನು ಎಲ್ಲ ವಸ್ತುಗಳ ಮೇಲೆ ಅಧಿಕಾರವನ್ನು ಹೊಂದಿದ್ದಾನೆ. ಅಲ್ಲಾಹನೇ, ನೀನು ನೀಡುವದನ್ನು ಯಾರೂ ತಡೆದುಕೊಳ್ಳಲಾರರು ಮತ್ತು ನೀನು ತಡೆಹಿಡಿಯುವದನ್ನು ಯಾರೂ ಕೊಡಲಾರರು. ಮತ್ತು ಶ್ರೀಮಂತನ ಸಂಪತ್ತು ನಿನಗೆ ವಿರುದ್ಧವಾಗಿ ಯಾವುದೇ ಪ್ರಯೋಜನವನ್ನು ಹೊಂದಿರುವುದಿಲ್ಲ.", "ಕಡ್ಡಾಯ ಪ್ರಾರ್ಥನೆಯ ಸಲಾಂ ನಂತರ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರತಿ ಕಡ್ಡಾಯ ಪ್ರಾರ್ಥನೆಯ ನಂತರ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_slaughtering" to DuaText("ಪ್ರಾಣಿಯನ್ನು ಕೊಲ್ಲುವಾಗ", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ, ಮತ್ತು ಅಲ್ಲಾಹನು ಶ್ರೇಷ್ಠನು.", "ಪ್ರಾಣಿಯನ್ನು ಬಲಿ ಅಥವಾ ವಧೆ ಮಾಡುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಯಜ್ಞದ ಸಮಯದಲ್ಲಿ ಬಿಸ್ಮಿಲ್ಲಾ ಮತ್ತು ತಕ್ಬೀರ್ ಎಂದು ಹೇಳಿದರು."),
        "dua_undressing" to DuaText("ಬಟ್ಟೆಗಳನ್ನು ತೆಗೆಯುವಾಗ", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ.", "ಬಟ್ಟೆಗಳನ್ನು ತೆಗೆಯುವಾಗ (ಗುಸ್ಸೆ ಅಥವಾ ಬದಲಾಯಿಸಲು).", "ಇದು ಜಿನ್ನನ ಕಣ್ಣುಗಳು ಮತ್ತು ವ್ಯಕ್ತಿಯ ಗುಪ್ತಾಂಗಗಳ ನಡುವಿನ ಪರದೆಯಾಗುತ್ತದೆ."),
        "dua_ilbas_jadidan" to DuaText("ಹೊಸ ಬಟ್ಟೆಗಳಲ್ಲಿ ಯಾರನ್ನಾದರೂ ನೋಡುವುದು", "ಹೊಸತನ್ನು ಧರಿಸಿ, ಶ್ಲಾಘನೀಯವಾಗಿ ಬದುಕಿ ಮತ್ತು ಹುತಾತ್ಮರಾಗಿ ಸಾಯಿರಿ.", "ಹೊಸ ಉಡುಪಿನಲ್ಲಿ ಮುಸ್ಲಿಂ ಸಹೋದರನನ್ನು ನೋಡಿದ ಮೇಲೆ.", "ಉಮರ್ (ರ) ಅವರನ್ನು ಹೊಸ ಉಡುಪಿನಲ್ಲಿ ನೋಡಿದ ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ದುಆ ಮಾಡಿದರು."),
        "dua_hajj_la_riya" to DuaText("ಪ್ರದರ್ಶನದಿಂದ ಮುಕ್ತವಾದ ಹಜ್", "ಓ ಅಲ್ಲಾಹನೇ, ಯಾವುದೇ ಪ್ರದರ್ಶನ ಮತ್ತು ಖ್ಯಾತಿಯ ಅನ್ವೇಷಣೆಯಿಲ್ಲದ ಹಜ್ (ಅದನ್ನು) ಮಾಡಿ.", "ಹಜ್ ಉದ್ದೇಶವನ್ನು ಮಾಡುವಾಗ ಪ್ರಾಮಾಣಿಕತೆಗಾಗಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಹಜ್ ಸಮಯದಲ್ಲಿ ಈ ದುಆವನ್ನು ಮಾಡಿದರು."),
        "dua_q_muslimayni_laka" to DuaText("ಇಬ್ರಾಹಿಂ ಮತ್ತು ಇಸ್ಮಾಯಿಲ್ (ಎ. ಎಸ್) ಅವರ ದುವಾ-ನಮ್ಮನ್ನು ವಿಧೇಯರನ್ನಾಗಿ ಮಾಡಿ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ಮತ್ತು ನಮ್ಮ ಸಂತತಿಗೆ ನಮಗೂ ಬದ್ಧತೆ ತೋರಿಸುವಂಥ ಒಂದು ಜನಾಂಗವನ್ನು ನೀನಾಗಿಸು. ನಮ್ಮ ಆರಾಧನೆಯ ವಿಧಿಗಳನ್ನು ನಮಗೆ ತೋರಿಸು ಮತ್ತು ನಮ್ಮ ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಸ್ವೀಕರಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಪಶ್ಚಾತ್ತಾಪಪಡುವವನು, ಕರುಣಾಮಯಿ.", "ತನಗಾಗಿ ಮತ್ತು ತನ್ನ ವಂಶಸ್ಥರಿಗಾಗಿ ಸಲ್ಲಿಸುವ ಒಂದು ದ್ವಂದ್ವ.", "ಕಾಬಾ ನಿರ್ಮಿಸುವಾಗ ಈ ದುಆವನ್ನು ನಿರ್ಮಿಸಲಾಯಿತು."),
        "dua_q_iftah_baynana" to DuaText("ಶುಐಬ್ (ಎ. ಎಸ್) ನ ದುವಾ-ನಮ್ಮ ನಡುವಿನ ನ್ಯಾಯಾಧೀಶ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಮತ್ತು ನಮ್ಮ ಜನರ ನಡುವೆ ನ್ಯಾಯತೀರ್ಪಿಗೆ ಸತ್ಯವನ್ನು ಹೇಳಿಕೊಡು. ಮತ್ತು ನೀನು ಅತ್ಯುತ್ತಮ ತೀರ್ಪುಗಾರನಾಗಿದ್ದೀ.", "ಸತ್ಯ ಮತ್ತು ಸುಳ್ಳಿನ ನಡುವಿನ ತೀರ್ಪುಗಾಗಿ.", "ಅವನ ಜನರು ಅವನನ್ನು ತಿರಸ್ಕರಿಸಿದಾಗ ಶುಐಬ್ (ಎ. ಎಸ್) ನ ದುಆ."),
        "dua_q_la_akuna_zahiran" to DuaText("ಮೂಸಾ (ಎ. ಎಸ್) ನ ದುವಾ-ಎಂದಿಗೂ ಅಪರಾಧಿಗಳ ಸಹಾಯಕನಲ್ಲ", "ನನ್ನ ಒಡೆಯನೇ, ನೀನು ನನಗೆ ನೀಡಿದ ಅನುಗ್ರಹದಿಂದಾಗಿ, ನಾನು ಎಂದಿಗೂ ಅಪರಾಧಿಗಳಿಗೆ ಸಹಾಯಕಾರಿಯಾಗುವುದಿಲ್ಲ.", "ಅಲ್ಲಾಹನ ಆಶೀರ್ವಾದಗಳಿಗೆ ಕೃತಜ್ಞತೆ ಮತ್ತು ತಪ್ಪಿತಸ್ಥರಿಗೆ ಸಹಾಯ ಮಾಡದಿರುವ ಪ್ರತಿಜ್ಞೆ.", "ಮೂಸಾ (ಅ. ಸ.) ತನ್ನ ಪಶ್ಚಾತ್ತಾಪದ ನಂತರ ಮಾಡಿದ ಪ್ರತಿಜ್ಞೆ."),
        "dua_q_nuh_unsurni" to DuaText("ನೂಹ್ (ಅ. ಸ.) ನ ದುವಾ-ನನಗೆ ಸಹಾಯ ಮಾಡಿ, ಅವರು ನನ್ನನ್ನು ನಿರಾಕರಿಸುತ್ತಾರೆ", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ಸಹಾಯ ಮಾಡು, ಏಕೆಂದರೆ ಅವರು ನನ್ನನ್ನು ನಿರಾಕರಿಸಿದ್ದಾರೆ.", "ಜನರು ನಿಮ್ಮನ್ನು ನಿರಾಕರಿಸಿದಾಗ ಮತ್ತು ಸತ್ಯವನ್ನು ತಿರಸ್ಕರಿಸಿದಾಗ.", "ನೂಹ್ (ಅ. ಸ.) ನ ದುಆ, ಇದಕ್ಕೆ ಉತ್ತರಿಸಲಾಯಿತು."),
        "dua_q_ihkum_bil_haqq" to DuaText("ನನ್ನ ಒಡೆಯನೇ, ಸತ್ಯದಿಂದ ತೀರ್ಪುತೀರ್ಪಡಿಸಿ.", "ನನ್ನ ಒಡೆಯನೇ, ಸತ್ಯದಿಂದ ತೀರ್ಪು ಮಾಡು. ಮತ್ತು ನಮ್ಮ ಒಡೆಯನು ಅತ್ಯಂತ ಕರುಣಾಮಯಿ. ನೀನು ವಿವರಿಸುವದರ ವಿರುದ್ಧ ಆತನ ಸಹಾಯವನ್ನು ಕೋರಲಾಗುತ್ತದೆ.", "ಸುಳ್ಳು ಮತ್ತು ಸುಳ್ಳು ಆರೋಪಗಳ ಎದುರಿನಲ್ಲಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರಿಗೆ ಒಂದು ದುಆ ಕಲಿಸಲಾಯಿತು."),
        "dua_ghalabatid_dayn" to DuaText("ಋಣಭಾರ ಮತ್ತು ಶತ್ರುಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗುವಿಕೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಸಾಲದಿಂದ ತುಂಬಿಕೊಳ್ಳುವುದರಿಂದ, ಶತ್ರುವಿನಿಂದ ಹೊರಗುಳಿಯುವುದರಿಂದ ಮತ್ತು ಶತ್ರುಗಳ ಹೊಗಳಿಕೆಯಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಸಾಲದ ಹೊರೆ ಮತ್ತು ಶತ್ರುಗಳ ಪ್ರಾಬಲ್ಯದಿಂದ ರಕ್ಷಣೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಈ ವಿಷಯಗಳಿಂದ ಆಶ್ರಯ ಪಡೆಯುತ್ತಿದ್ದರು."),
        "dua_faqr_qillah_dhillah" to DuaText("ಬಡತನ ಮತ್ತು ಅವಮಾನದಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಬಡತನ, ಕೊರತೆ ಮತ್ತು ಅವಮಾನದಿಂದ ಮತ್ತು ಇತರರಿಗೆ ಅನ್ಯಾಯ ಮಾಡುವುದರಿಂದ ಅಥವಾ ಅನ್ಯಾಯವಾಗುವುದರಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಬಯಸುತ್ತೇನೆ.", "ಕಷ್ಟ, ಕೊರತೆ ಮತ್ತು ಅವಮಾನದಿಂದ ಸುರಕ್ಷಿತವಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಕಲಿಸಿದ ಆಶ್ರಯ."),
        "dua_five_things_new_muslim" to DuaText("ಕ್ಷಮಿಸಿ, ಕರುಣೆ ತೋರಿಸಿ, ಮಾರ್ಗದರ್ಶನ ನೀಡಿ, ಗುಣಪಡಿಸಿ, ಒದಗಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು, ನನ್ನ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು, ನನಗೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡು, ನನಗೆ ಕ್ಷೇಮವನ್ನು ಕೊಡು ಮತ್ತು ನನಗೆ ಪೋಷಣೆ ಮಾಡು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಹೊಸ ಮುಸ್ಲಿಮರಿಗೆ ಪ್ರಾರ್ಥನೆಯೊಂದಿಗೆ ಈ ದುಆವನ್ನು ಕಲಿಸಿದರು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಹೇಳಿದರುಃ ಈ ಪದಗಳು ನಿಮಗಾಗಿ ಈ ಜಗತ್ತನ್ನು ಮತ್ತು ಪರಲೋಕವನ್ನು ಒಟ್ಟುಗೂಡಿಸುತ್ತವೆ."),
        "dua_ruku_laka_raka_tu" to DuaText("ರುಕುನಲ್ಲಿ-ನಿನಗೆ ನಾನು ತಲೆಬಾಗಿದೆನು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನಗೆ ತಲೆಬಾಗುತ್ತೇನೆ. ನಿನ್ನಲ್ಲಿ ನಾನು ನಂಬಿಕೆ ಇಟ್ಟಿದ್ದೇನೆ ಮತ್ತು ನಿನಗೆ ಶರಣಾಗಿದ್ದೇನೆ. ನನ್ನ ಶ್ರವಣ, ನನ್ನ ದೃಷ್ಟಿ, ನನ್ನ ಮನಸ್ಸು, ನನ್ನ ಎಲುಬುಗಳು ಮತ್ತು ನನ್ನ ನರಕೋಶಗಳು ನಿನ್ನ ಮುಂದೆ ವಿನಮ್ರವಾಗಿವೆ.", "ರುಕುನಲ್ಲಿ (ವಿಶೇಷವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತ ಪ್ರಾರ್ಥನೆಗಳಲ್ಲಿ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಇದನ್ನು ರುಕುವಿನಲ್ಲಿ ಪಠಿಸಿದರು."),
        "dua_sujood_laka_sajadtu" to DuaText("ಸುಜೂದ್-ಟು ಯು ನಾನು ಪ್ರಾಸ್ಟ್ರೇಟ್ ಮಾಡಿದ್ದೇನೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನಗೆ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡಿದ್ದೇನೆ. ನಿನ್ನಲ್ಲಿ ನಾನು ನಂಬಿಕೆ ಇಟ್ಟಿದ್ದೇನೆ ಮತ್ತು ನಿನಗೆ ಶರಣಾಗಿದ್ದೇನೆ. ನನ್ನ ಮುಖವು ಅದನ್ನು ಸೃಷ್ಟಿಸಿದ, ರೂಪಿಸಿದ ಮತ್ತು ಅದರ ಶ್ರವಣ ಮತ್ತು ದೃಷ್ಟಿಯನ್ನು ಹೊರತಂದವನಿಗೆ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡಿದೆ. ಸೃಷ್ಟಿಸಿದವರಲ್ಲಿ ಅತ್ಯುತ್ತಮನಾದ ಅಲ್ಲಾಹನು ಧನ್ಯನು.", "ಸುಜೂದ್ನಲ್ಲಿ (ವಿಶೇಷವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತ ಪ್ರಾರ್ಥನೆಗಳಲ್ಲಿ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಇದನ್ನು ಸುಜೂದ್ನಲ್ಲಿ ಪಠಿಸಿದರು."),
        "dua_ruku_sujood_subhanaka" to DuaText("ಮಹಿಮೆ ನಿನಗೆ ಇರಲಿ, ನಮ್ಮ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ನಮ್ಮ ಒಡೆಯನಾದ ಅಲ್ಲಾಹನೇ, ನಿನಗೆ ಮಹಿಮೆ ಇರಲಿ ಮತ್ತು ನಿನಗೆ ಸ್ತುತಿಯಿರಲಿ. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ರುಕು ಮತ್ತು ಸುಜೂದ್ನಲ್ಲಿ.", "ಆಯಿಷಾ (ರ.): ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಇದನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ರುಕು ಮತ್ತು ಸುಜೂದ್ನಲ್ಲಿ ಹೇಳುತ್ತಾರೆ."),
        "dua_q_musa_li_akhi" to DuaText("ಮೂಸಾ (ಅ. ಸ.) ರ ದುವಾ-ನನ್ನನ್ನು ಮತ್ತು ನನ್ನ ಸಹೋದರನನ್ನು ಕ್ಷಮಿಸಿ.", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಮತ್ತು ನನ್ನ ಸಹೋದರನನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ನಿನ್ನ ಕರುಣೆಯಲ್ಲಿ ನಮ್ಮನ್ನು ಸೇರಿಸು, ಯಾಕೆಂದರೆ ನೀನು ಕರುಣೆಯುಳ್ಳವರಲ್ಲಿ ಅತ್ಯಂತ ಕರುಣೆಯುಳ್ಳವನಾಗಿದ್ದೀ.", "ತನ್ನ ಮತ್ತು ತನ್ನ ಸಹೋದರ ಅಥವಾ ಪ್ರೀತಿಪಾತ್ರರನ್ನು ಕ್ಷಮಿಸಿ.", "ಹಾರೂನ್ (ಎ. ಎಸ್) ಗಾಗಿ ಮೂಸಾದ (ಎ. ಎಸ್) ದುಆ."),
        "dua_q_ufawwidu_amri" to DuaText("ನಾನು ನನ್ನ ವ್ಯವಹಾರವನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುತ್ತೇನೆ.", "ಮತ್ತು ನಾನು ನನ್ನ ವ್ಯವಹಾರವನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುತ್ತೇನೆ. ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹ್ ತನ್ನ ಸೇವಕರನ್ನು ನೋಡುತ್ತಾನೆ.", "ಜನರು ನಿಮ್ಮನ್ನು ವಿರೋಧಿಸಿದಾಗ ಮತ್ತು ವಿಷಯವನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಬಿಡಬೇಕು.", "ಫರೋಹನ ಜನರ ನಂಬಿಕೆಯುಳ್ಳವರ ಮಾತುಗಳು; ಅಲ್ಲಾಹ್ ಅವರನ್ನು ಅವರ ದುಷ್ಟ ಸಂಚುಗಳಿಂದ ರಕ್ಷಿಸಿದನು."),
        "dua_q_hawariyyun" to DuaText("ಶಿಷ್ಯರ ದುವಾ-ಸಾಕ್ಷಿಗಳೊಂದಿಗೆ ನಮ್ಮನ್ನು ದಾಖಲಿಸಿ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ಪ್ರಕಟಿಸಿದ್ದನ್ನು ನಾವು ನಂಬಿದ್ದೇವೆ ಮತ್ತು ನಾವು ದೂತರನ್ನು ಅನುಸರಿಸಿದ್ದೇವೆ. ಆದ್ದರಿಂದ ನಮ್ಮನ್ನು ಸಾಕ್ಷಿಗಳ ಪಟ್ಟಿಯಲ್ಲಿ ದಾಖಲಿಸು.", "ನಂಬಿಕೆಯಲ್ಲಿ ಮತ್ತು ಸಂದೇಶವಾಹಕನನ್ನು ಅನುಸರಿಸುವಲ್ಲಿ ಸ್ಥಿರತೆಗಾಗಿ.", "ಇಸಾ (ಎ. ಎಸ್) ಅವರ ಶಿಷ್ಯರ ದುಆ."),
        "dua_q_la_tukhzini" to DuaText("ಇಬ್ರಾಹಿಂನ ದುವಾ (ಅ. ಸ.)-ನನಗೆ ಅವಮಾನ ಮಾಡಬೇಡಿ.", "ಮತ್ತು ಅವರು ಪುನರುತ್ಥಾನಗೊಳ್ಳುವ ದಿನದಂದು ನನಗೆ ಅವಮಾನ ಮಾಡಬೇಡಿ.", "ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಅವಮಾನದಿಂದ ಸುರಕ್ಷಿತವಾಗಿರಲು.", "ಇಬ್ರಾಹಿಮ್ (ಅ. ಸ.) ಅವರ ಪುಣ್ಯತಿಥಿ."),
        "dua_iftar_laka_sumtu" to DuaText("ಇಫ್ತಾರ್-ನಿಮಗಾಗಿ ನಾನು ಉಪವಾಸ ಮಾಡಿದೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನಗಾಗಿ ಉಪವಾಸ ಮಾಡಿದ್ದೇನೆ ಮತ್ತು ನಿನ್ನ ಆಹಾರದಿಂದ ನನ್ನ ಉಪವಾಸವನ್ನು ಮುರಿಯುತ್ತೇನೆ.", "ಉಪವಾಸವನ್ನು ಮುರಿಯುವಾಗ (ಪ್ರಸಿದ್ಧ ಇಫ್ತಾರ್ ದುಆ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಇಫ್ತಾರ್ನಲ್ಲಿ ಇದನ್ನು ಹೇಳಿದರು. ಇದು ಇತರ ಕಥನಗಳಿಂದ ಬಲಗೊಂಡ ಮುರ್ಸಾ ಕಥನವಾಗಿದೆ; ಇಫ್ತಾರ್ನಲ್ಲಿ ಅದನ್ನು ಪಠಿಸುವುದು ಹನಾಫಿಗಳು ಮತ್ತು ಬಹುಪಾಲು ಜನರ ಅಭ್ಯಾಸವಾಗಿದೆ."),
        "dua_iftar_ibn_umar" to DuaText("ಇಫ್ತಾರ್-ನಿಮ್ಮ ಅಪಾರ ಕರುಣೆಯಿಂದ, ನನ್ನನ್ನು ಕ್ಷಮಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸುವಂತೆ ನಾನು ನಿನ್ನ ಕರುಣೆಯಿಂದ, ಎಲ್ಲವನ್ನು ಒಳಗೊಳ್ಳುವ ಮೂಲಕ ನಿನ್ನನ್ನು ಕೋರುತ್ತೇನೆ.", "ಇಫ್ತಾರ್ನಲ್ಲಿ-ಅಬ್ದುಲ್ಲಾ ಇಬ್ನ್ ಅಮರ್ (ರ.) ಈ ದುಆವನ್ನು ಮಾಡಿದರು; ಇಫ್ತಾರ್ನಲ್ಲಿ ಉಪವಾಸ ಮಾಡುವ ವ್ಯಕ್ತಿಯ ದುಆವನ್ನು ತಿರಸ್ಕರಿಸಲಾಗುವುದಿಲ್ಲ.", "ಹದೀಸ್ಃ ಇಫ್ತಾರ್ ಸಮಯದಲ್ಲಿ ಉಪವಾಸ ಮಾಡುವ ವ್ಯಕ್ತಿಯ ದುಆವನ್ನು ತಿರಸ್ಕರಿಸಲಾಗುವುದಿಲ್ಲ."),
        "dua_inni_saim" to DuaText("ಉಪವಾಸ ಮಾಡುವಾಗ ಪ್ರಚೋದಿಸಿದಾಗ", "ನಾನು ಉಪವಾಸ ಮಾಡುತ್ತಿದ್ದೇನೆ, ಉಪವಾಸ ಮಾಡುತ್ತಿದ್ದೇನೆ.", "ಉಪವಾಸ ಮಾಡುವಾಗ ಯಾರಾದರೂ ನಿಮ್ಮನ್ನು ಅವಮಾನಿಸಿದಾಗ ಅಥವಾ ನಿಮ್ಮೊಂದಿಗೆ ಜಗಳವಾಡಿದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಹೇಳಿದರುಃ ಉಪವಾಸವು ಒಂದು ಗುರಾಣಿಯಾಗಿದೆ, ಆದ್ದರಿಂದ ಉಪವಾಸ ಮಾಡುವ ವ್ಯಕ್ತಿಯು ಅಶ್ಲೀಲವಾಗಿ ಮಾತನಾಡಬಾರದು ಅಥವಾ ಅಜ್ಞಾನದಿಂದ ವರ್ತಿಸಬಾರದು-ಯಾರಾದರೂ ಜಗಳವಾಡಿದರೆ, ಇದನ್ನು ಎರಡು ಬಾರಿ ಹೇಳಿ."),
        "dua_eid_takbeer" to DuaText("ಈದ್ಗೆ ಹೋಗುವ ದಾರಿಯಲ್ಲಿ ತಕ್ಬೀರ್", "ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠ, ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠ, ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರುಗಳಿಲ್ಲ, ಮತ್ತು ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠ, ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠ, ಮತ್ತು ಎಲ್ಲಾ ಪ್ರಶಂಸೆಗಳು ಅಲ್ಲಾಹನದೇ.", "ಚಂದ್ರನ ದರ್ಶನದ ರಾತ್ರಿಯಿಂದ ಈದ್ ಅಲ್-ಫಿತರ್ ಪ್ರಾರ್ಥನೆಯವರೆಗೆ, ವಿಶೇಷವಾಗಿ ಈದ್ ಮೈದಾನಕ್ಕೆ ಹೋಗುವ ದಾರಿಯಲ್ಲಿ.", "ಕುರಾನ್ ಆಜ್ಞೆಃ'ನೀವು ಎಣಿಕೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ ಅಲ್ಲಾಹುವಿನ ಶ್ರೇಷ್ಠತೆಯನ್ನು ಘೋಷಿಸಲು'(ಅಲ್-ಬಖರಾ 2:185). ಇಬ್ನ್ ಮಸೂದ್ (ರಾ.) ಈ ತಕ್ಬೀರ್ ಅನ್ನು ಹೇಳಿದರು."),
        "dua_ahsin_aqibatana" to DuaText("ಎಲ್ಲಾ ವಿಷಯಗಳಲ್ಲೂ ನಮ್ಮ ಅಂತ್ಯವನ್ನು ಒಳ್ಳೆಯದಾಗಿಸಿಕೊಳ್ಳಿ", "ಓ ಅಲ್ಲಾಹನೇ, ಎಲ್ಲಾ ವಿಷಯಗಳಲ್ಲೂ ನಮ್ಮ ಅಂತ್ಯವನ್ನು ಒಳ್ಳೆಯದಾಗಿಸು ಮತ್ತು ಈ ಜಗತ್ತಿನಲ್ಲಿ ಅವಮಾನ ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ಶಿಕ್ಷೆಯಿಂದ ನಮ್ಮನ್ನು ರಕ್ಷಿಸು.", "ಪ್ರತಿಯೊಂದು ವಿಷಯದಲ್ಲೂ ಉತ್ತಮ ಫಲಿತಾಂಶಕ್ಕಾಗಿ.", "ಯಾರು ಈ ದುಆ ಮಾಡಿ, ವಿಚಾರಣೆಗೂ ಮುನ್ನ ಸಾಯುತ್ತಾರೋ ಅವರು ಸಾಯುತ್ತಾರೆ (ವಿಚಾರಣೆಯಿಂದ ಸುರಕ್ಷಿತವಾಗಿ)."),
        "dua_fadlika_wa_rahmatik" to DuaText("ನಾನು ನಿಮ್ಮ ಅನುಗ್ರಹ ಮತ್ತು ಕರುಣೆಯನ್ನು ಕೋರುತ್ತೇನೆ.", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನ ಅನುಗ್ರಹ ಮತ್ತು ಕರುಣೆಯನ್ನು ಕೋರುತ್ತೇನೆ, ಏಕೆಂದರೆ ನಿನ್ನ ಹೊರತು ಬೇರೆ ಯಾರೂ ಅದನ್ನು ಹೊಂದಿಲ್ಲ.", "ಒದಗಿಸುವಿಕೆ ಮತ್ತು ಕರುಣೆಯನ್ನು ಕೇಳುವಾಗ.", "ಆಹಾರವಿಲ್ಲದ ಸಮಯದಲ್ಲಿ ಅತಿಥಿಗಳು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಬಳಿಗೆ ಬಂದರು; ಅವರು ಈ ದುಆವನ್ನು ಮಾಡಿದರು, ಮತ್ತು ನಂತರ ಉಡುಗೊರೆ ಬಂದಿತು."),
        "dua_allahu_akbar_kabira_2696" to DuaText("ಬೆಡೋಯಿನ್ಗೆ ಕಲಿಸಿದ ಪದಗಳು", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದೆ ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಅಲ್ಲಾಹನು ಅತ್ಯಂತ ದೊಡ್ಡವನು, ಅಪಾರವಾದ ಸ್ತುತಿಯು ಅಲ್ಲಾಹನಿಗಿದೆ; ಮಹಿಮೆಯು ಲೋಕಗಳ ಒಡೆಯನಾದ ಅಲ್ಲಾಹನಿಗೆ; ಮತ್ತು ಸರ್ವಶಕ್ತ, ವಿವೇಕಶಾಲಿ ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಯಾವುದೇ ಶಕ್ತಿ ಅಥವಾ ಶಕ್ತಿ ಇಲ್ಲ.", "ಬೆಡೋಯಿನ್ಗೆ ಕಲಿಸಿದ ಧಿಕ್ರ್ ಮತ್ತು ದುಆ ಎಂಬ ಸಮಗ್ರ ನುಡಿಗಟ್ಟು.", "ಇದರ ನಂತರ ಅವರಿಗೆ'ಅಲ್ಲಾಹುಮಾಘಫಿರ್ ಲಿ ವಾರ್ಹಮ್ನಿ ವಾಹ್ದಿನಿ ವಾರ್ಜುಕ್ನಿ'ಎಂದು ಹೇಳಲು ಕಲಿಸಲಾಯಿತು."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("ನಾನು ಮೊದಲು ಮತ್ತು ನಂತರ ಕಳುಹಿಸಿದ್ದನ್ನು ಕ್ಷಮಿಸಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಮೊದಲು ಮತ್ತು ನಂತರ ಮಾಡಿದ ಪಾಪಗಳನ್ನು, ನಾನು ರಹಸ್ಯವಾಗಿ ಏನು ಮಾಡಿದ್ದೇನೆ ಮತ್ತು ಬಹಿರಂಗವಾಗಿ ಏನು ಮಾಡಿದ್ದೇನೆ, ನನ್ನ ಮಿತಿಮೀರಿದ ಕೃತ್ಯಗಳನ್ನು ಮತ್ತು ನನಗಿಂತ ಚೆನ್ನಾಗಿ ನಿನಗೆ ತಿಳಿದಿರುವದನ್ನು ನನಗೆ ಕ್ಷಮಿಸು. ನೀನು ಮುಂದೆ ತರುತ್ತಿರುವವನು ಮತ್ತು ಹಿಂದಿರುಗಿಸುವವನು. ನಿನ್ನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ದೇವರು ಇಲ್ಲ.", "ತಾಶಹುದ್ ಮತ್ತು ಸಲಾವತ್ ನಂತರ, ಸಲಾಂ ಮೊದಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಪ್ರಾರ್ಥನೆಯ ಕೊನೆಯಲ್ಲಿ, ತಾಷಹುದ್ ಮತ್ತು ಸಲಾಂ ನಡುವೆ ಇದನ್ನು ಪಠಿಸಿದರು."),
        "dua_jiddi_wa_hazli" to DuaText("ನನ್ನ ಗಂಭೀರತೆ ಮತ್ತು ನನ್ನ ಹಾಸ್ಯವನ್ನು ಕ್ಷಮಿಸಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಗಂಭೀರವಾಗಿ ಮತ್ತು ತಮಾಷೆಯಾಗಿ, ತಪ್ಪಾಗಿ ಮತ್ತು ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ಮಾಡಿದ ಪಾಪಗಳನ್ನು ನನಗೆ ಕ್ಷಮಿಸು-ಮತ್ತು ಅದೆಲ್ಲವೂ ನನ್ನಲ್ಲಿದೆ.", "ತಿಳಿದಿರುವ ಮತ್ತು ತಿಳಿದಿಲ್ಲದ ಎಲ್ಲಾ ರೀತಿಯ ಪಾಪಗಳಿಗೂ ಕ್ಷಮೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಸಮಗ್ರ ಇಸ್ತಿಘಫರ್."),
        "dua_rising_ruku_mil" to DuaText("ರುಕುವಿನ ನಂತರ-ಸ್ವರ್ಗವನ್ನು ತುಂಬಿದ ಪ್ರಶಂಸೆ", "ನಮ್ಮ ಒಡೆಯನೇ, ಆಕಾಶಗಳನ್ನು ತುಂಬುವ, ಭೂಮಿಯನ್ನು ತುಂಬುವ ಮತ್ತು ಅದರ ನಂತರ ನೀನು ಬಯಸುವ ಎಲ್ಲವನ್ನೂ ತುಂಬುವ ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ನಿನಗೆ ಸೇರಿದ್ದು.", "ರುಕುವಿನಿಂದ ಎದ್ದ ನಂತರ,'ರಬ್ಬಾನಾ ಲಾಕಲ್-ಹಮ್ದ್'ನೊಂದಿಗೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ರುಕುವಿನಿಂದ ಎದ್ದ ಮೇಲೆ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_istiftah_kabira" to DuaText("ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠ, ಅಪಾರವಾಗಿ ಸ್ತುತಿಸಲ್ಪಡುವವನು.", "ಅಲ್ಲಾಹ್ ಅತ್ಯಂತ ಶ್ರೇಷ್ಠನಾಗಿದ್ದಾನೆ; ಅಲ್ಲಾಹನಿಗೆ ಅಪಾರವಾದ ಸ್ತುತಿಯಿದೆ; ಮತ್ತು ಬೆಳಗಿನ ಮತ್ತು ಸಂಜೆಯ ಅಲ್ಲಾಹನಿಗೆ ಮಹಿಮೆ ಇರಲಿ.", "ಪ್ರಾರ್ಥನೆಯನ್ನು ಪ್ರಾರಂಭಿಸುವಾಗ (ಆರಂಭಿಕ ಸ್ತುತಿಯ ಒಂದು ರೂಪ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಹೀಗೆ ಹೇಳಿದರುಃ ಸ್ವರ್ಗದ ಬಾಗಿಲುಗಳು ಇದಕ್ಕಾಗಿ ತೆರೆಯಲ್ಪಟ್ಟವು."),
        "dua_q_ashku_bathhi" to DuaText("ಯಾಕೂಬ್ (ಅ. ಸ.) ನ ದುವಾ-ನಾನು ಅಲ್ಲಾಹನಿಗೆ ಮಾತ್ರ ದೂರು ನೀಡುತ್ತೇನೆ.", "ನನ್ನ ನೋವು ಮತ್ತು ನನ್ನ ದುಃಖವನ್ನು ನಾನು ಅಲ್ಲಾಹನಿಗೆ ಮಾತ್ರ ದೂರುತ್ತೇನೆ.", "ಆಳವಾದ ದುಃಖ ಮತ್ತು ಬೇರ್ಪಡುವಿಕೆಯಲ್ಲಿ.", "ಯೂಸುಫ್ (ಎ. ಎಸ್) ನಿಂದ ಬೇರ್ಪಟ್ಟಾಗ ಯಾಕುಬ್ (ಎ. ಎಸ್) ಇದನ್ನು ಹೇಳಿದನು."),
        "dua_q_khayrun_hafiza" to DuaText("ಅಲ್ಲಾಹ್ ಅತ್ಯುತ್ತಮ ರಕ್ಷಕನಾಗಿದ್ದಾನೆ.", "ಅಲ್ಲಾಹ್ ಅತ್ಯುತ್ತಮ ರಕ್ಷಕನಾಗಿದ್ದಾನೆ ಮತ್ತು ಕರುಣಾಮಯಿಗಳಲ್ಲಿ ಅತ್ಯಂತ ಕರುಣಾಮಯಿ.", "ಮಕ್ಕಳು ಅಥವಾ ಪ್ರೀತಿಪಾತ್ರರನ್ನು ಪ್ರಯಾಣಕ್ಕೆ ಕಳುಹಿಸುವಾಗ.", "ಯಾಕುಬ್ (ಅ. ಸ.) ತನ್ನ ಮಗನನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುವಾಗ ಈ ಮಾತನ್ನು ಹೇಳಿದನು."),
        "dua_q_aqraba_rashada" to DuaText("ನನ್ನ ಒಡೆಯನು ನನಗೆ ಬಲಕ್ಕೆ ಹತ್ತಿರವಾಗುವಂತೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡಲಿ.", "ಬಹುಶಃ ನನ್ನ ಒಡೆಯನು ನನಗೆ ಇದಕ್ಕಿಂತ ಹತ್ತಿರವಿರುವ ಸರಿಯಾದ ನಡವಳಿಕೆಯತ್ತ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತಾನೆ.", "ಕೆಲವು ವಿಷಯಗಳಲ್ಲಿ ಉತ್ತಮ ಮಾರ್ಗವನ್ನು ಹುಡುಕುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರಿಗೆ ಮರೆತುಹೋದ ನಂತರ ಇದನ್ನು ಹೇಳಲು ಹೇಳಲಾಯಿತು."),
        "dua_q_sawa_as_sabil" to DuaText("ಮೂಸಾ (ಅ. ಸ.) ರ ದುವಾ-ನನಗೆ ಸರಿಯಾದ ಮಾರ್ಗವನ್ನು ತೋರಿಸಿ", "ಬಹುಶಃ ನನ್ನ ಒಡೆಯನು ನನಗೆ ಸರಿಯಾದ ಮಾರ್ಗವನ್ನು ತೋರಿಸುತ್ತಾನೆ.", "ಹೊಸ ಪ್ರಯಾಣ ಅಥವಾ ಅಪರಿಚಿತ ರಸ್ತೆಗೆ ಹೊರಟಾಗ.", "ಮೂಸಾ (ಎ. ಎಸ್) ಅವರು ಮಾದ್ಯಾನ್ನ ಕಡೆಗೆ ತಿರುಗಿದಾಗ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_q_not_among_wrongdoers" to DuaText("ನನ್ನನ್ನು ತಪ್ಪಿತಸ್ಥರ ಗುಂಪಿನಲ್ಲಿ ಸೇರಿಸಬೇಡಿ.", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಅಕ್ರಮ ಮಾಡುವವರ ಗುಂಪಿನಲ್ಲಿರಿಸಬೇಡ.", "ಒಬ್ಬನನ್ನು ತಪ್ಪಿತಸ್ಥರಿಂದ ದೂರವಿಡುವಂತೆ ಅಲ್ಲಾಹನನ್ನು ಕೇಳುವ ಒಂದು ದುಆ.", "ಒಬ್ಬನನ್ನು ತಪ್ಪಿತಸ್ಥರಿಂದ ದೂರವಿಡುವಂತೆ ಅಲ್ಲಾಹನನ್ನು ಕೇಳುವ ಒಂದು ದುಆ."),
        "dua_q_do_not_make_us_trial" to DuaText("ನಮ್ಮನ್ನು ವಿಚಾರಣೆಗೆ ಒಳಪಡಿಸಬೇಡಿ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ನೀವು ಅವಿಶ್ವಾಸಿಗಳಿಗೆ ಪರೀಕ್ಷೆಯಾಗಿ ಮಾಡಬೇಡಿ. ಮತ್ತು ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ಕ್ಷಮಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಸರ್ವಶಕ್ತನೂ, ತತ್ವಜ್ಞನೂ ಆಗಿದ್ದೀ.", "ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಮತ್ತು ಅವನ ಸಹಚರರ ದುಆ.", "ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಮತ್ತು ಅವನ ಸಹಚರರ ದುಆ."),
        "dua_morning_witness" to DuaText("ತೌಹೀದನಿಗೆ ಬೆಳಗಿನ ಸಾಕ್ಷಿ", "ಓ ಅಲ್ಲಾಹ್ವೇ, ನಿನ್ನ ಸಿಂಹಾಸನದ ಧಾರಕರೇ, ನಿನ್ನ ದೇವತೆಗಳೇ, ಮತ್ತು ನಿನ್ನ ಎಲ್ಲಾ ಸೃಷ್ಟಿಗಳೂ, ನಿನ್ನನ್ನು, ನೀನು ಅಲ್ಲಾಹ್ ಎಂದು, ನಿನ್ನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ದೇವರು ಇಲ್ಲ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲ, ಮತ್ತು ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ನಿನ್ನ ಸೇವಕ ಮತ್ತು ಸಂದೇಶವಾಹಕನೆಂದು ಸಾಕ್ಷಿಯಾಗುವಂತೆ ನಾನು ಬೆಳಿಗ್ಗೆ ಕರೆದಿದ್ದೇನೆ.", "ಇದನ್ನು ಬೆಳಿಗ್ಗೆ ನಾಲ್ಕು ಬಾರಿ ಹೇಳಿರುವುದನ್ನು ಕಥನವು ಉಲ್ಲೇಖಿಸುತ್ತದೆ.", "ಇದನ್ನು ಬೆಳಿಗ್ಗೆ ನಾಲ್ಕು ಬಾರಿ ಹೇಳಿರುವುದನ್ನು ಕಥನವು ಉಲ್ಲೇಖಿಸುತ್ತದೆ."),
    )
}
